internal static string FormatExpirationTooltip(DateTimeOffset expiration, CultureInfo culture)
{
    var timePattern = culture.DateTimeFormat.ShortTimePattern;
    return $"{Resources.AWAKE_TRAY_UNTIL} {expiration.ToString($"MMM d, {timePattern}", culture)}";
}

case AwakeMode.EXPIRABLE:
