    icon = TrayHelper.ExpirableIcon;
    break;

[TestMethod]
public void FormatsExpirationWithCurrentCulture()
{
    var expiration = new DateTimeOffset(2030, 1, 2, 13, 30, 0, TimeSpan.Zero);
    var text = AwakeTrayTextFormatter.FormatExpirationTooltip(expiration, new CultureInfo("sv-SE"));
    StringAssert.Contains(text, "13:30");
}
